const [selectedStore, setSelectedStore] = useState<string>("all");
const [selectedReason, setSelectedReason] = useState<string>("all");
const [productFilter, setProductFilter] = useState<string>("");

// Report Dialog State
const [reportOpen, setReportOpen] = useState(false);
const [reportReasons, setReportReasons] = useState<Set<string>>(new Set());
const [reportColumns, setReportColumns] = useState<Set<string>>(new Set([
    'data', 'loja', 'produto', 'quantidade', 'unidade', 'preco_unit', 'valor_total', 'motivo', 'responsavel'
]));

// Extract unique reasons for filter
const uniqueReasons = useMemo(() => {
    const reasons = new Set(losses.map(l => l.motivo_perda).filter(Boolean));
    return Array.from(reasons).sort();
}, [losses]);

const openReportDialog = () => {
    setReportReasons(new Set(uniqueReasons));
    setReportOpen(true);
};

const toggleReportReason = (reason: string) => {
    setReportReasons(prev => {
        const next = new Set(prev);
        if (next.has(reason)) next.delete(reason);
        else next.add(reason);
        return next;
    });
};

const toggleReportColumn = (col: string) => {
    setReportColumns(prev => {
        const next = new Set(prev);
        if (next.has(col)) next.delete(col);
        else next.add(col);
        return next;
    });
};

const REPORT_COLUMN_OPTIONS = [
    { key: 'data', label: 'Data' },
    { key: 'loja', label: 'Loja' },
    { key: 'produto', label: 'Produto' },
    { key: 'quantidade', label: 'Quantidade' },
    { key: 'unidade', label: 'Unidade' },
    { key: 'preco_unit', label: 'Preço Unitário' },
    { key: 'valor_total', label: 'Valor Total' },
    { key: 'motivo', label: 'Motivo da Perda' },
    { key: 'responsavel', label: 'Responsável' },
    { key: 'lote', label: 'Lote' },
    { key: 'observacoes', label: 'Observações' },
];

// --- Filter Logic ---
const filteredLosses = useMemo(() => {
    if (!dateRange?.from) return losses;

    return losses.filter(l => {
        // 1. Date Filter
        if (!l.data_identificacao) return false;
        const date = parseISO(l.data_identificacao);
        if (!isValid(date)) return false;

        const from = dateRange.from as Date;
        const to = dateRange.to || dateRange.from || new Date();

        const target = date.getTime();
        const startStr = new Date(from).setHours(0, 0, 0, 0);
        const endStr = new Date(to).setHours(23, 59, 59, 999);

        if (target < startStr || target > endStr) return false;

        // 2. Store Filter
        if (selectedStore !== "all" && String(l.loja_id) !== selectedStore) return false;

        // 3. Reason Filter
        if (selectedReason !== "all" && l.motivo_perda !== selectedReason) return false;

        // 4. Product Filter
        if (productFilter && !((l.produto_nome_perda || "").toLowerCase().includes(productFilter.toLowerCase()))) return false;

        return true;
    });
}, [losses, dateRange, selectedStore, selectedReason, productFilter]);

// --- Analytics Logic ---
const analytics = useMemo(() => {
    const totalRecords = filteredLosses.length;
    const totalQuantity = filteredLosses.reduce((acc, curr) => acc + (Number(curr.quantidade) || 0), 0);
    const totalValue = filteredLosses.reduce((acc, curr) => acc + (Number(curr.valor_estimado) || 0), 0);

    // Daily Averages
    const daysDiff = dateRange?.from && dateRange?.to
        ? Math.max(1, differenceInDays(dateRange.to, dateRange.from) + 1) // +1 to include both start and end dates
        : 30;

    const avgDailyQty = totalQuantity / daysDiff;
    const avgDailyVal = totalValue / daysDiff;

    // Grouping Logic (Dynamic: Day if < 60 days, Month otherwise)
    const isDailyGroup = daysDiff < 60;

    const byHour: Record<number, number> = {};
    const byUser: Record<number, number> = {};
    const byStore: Record<string, number> = {};         // Qty
    const byStoreValue: Record<string, number> = {};    // Value
    const byProduct: Record<string, number> = {};       // Qty
    const byProductValue: Record<string, number> = {};  // Value
    const byTime: Record<string, { date: string; quantity: number; value: number; logs: number }> = {};
    const storeByTimeRaw: Record<string, any> = {};

    // Detailed List for Modal/Table
    const detailedList = [...filteredLosses].map(l => ({
        ...l,
        val: Number(l.valor_estimado) || 0,
        qty: Number(l.quantidade) || 0,
        prod: l.produto_nome_perda || "Desconhecido",
        store: l.stores?.nome || "Outra",
        date: l.data_identificacao
    })).sort((a, b) => b.val - a.val);

    filteredLosses.forEach(l => {
        const date = l.data_identificacao ? parseISO(l.data_identificacao) : new Date();
        const hour = getHours(date);

        // Dynamic Key
        const timeKey = isDailyGroup ? format(date, "yyyy-MM-dd") : format(date, "yyyy-MM");
        const timeLabel = isDailyGroup ? format(date, "dd/MM") : format(date, "MMM/yy", { locale: ptBR });

        let qty = Number(l.quantidade) || 0;
        const val = Number(l.valor_estimado) || 0;
        const u = l.unidade ? l.unidade.toLowerCase() : 'uni';
        if (u === 'g' || u === 'ml') qty = qty / 1000;

        const storeName = l.stores?.nome || "Outra";
        const prod = l.produto_nome_perda || "Desconhecido";

        byHour[hour] = (byHour[hour] || 0) + 1;
        if (l.responsavel_id) byUser[l.responsavel_id] = (byUser[l.responsavel_id] || 0) + 1;

        byStore[storeName] = (byStore[storeName] || 0) + qty;
        byStoreValue[storeName] = (byStoreValue[storeName] || 0) + val;

        byProduct[prod] = (byProduct[prod] || 0) + qty;
        byProductValue[prod] = (byProductValue[prod] || 0) + val;

        if (!byTime[timeKey]) byTime[timeKey] = { date: timeKey, quantity: 0, value: 0, logs: 0 };
        byTime[timeKey].quantity += qty;
        byTime[timeKey].value += val;
        byTime[timeKey].logs += 1;

        // Stacked/Line Data
        if (!storeByTimeRaw[timeKey]) {
            storeByTimeRaw[timeKey] = { name: timeLabel, rawDate: timeKey };
        }
        // Ensure all stores are initialized to 0 if not present (optional, but good for lines) or rely on recharts connectNulls
        // Ensure all stores are initialized to 0 if not present (optional, but good for lines) or rely on recharts connectNulls
        storeByTimeRaw[timeKey][storeName] = (storeByTimeRaw[timeKey][storeName] || 0) + qty;
    });

