const [selectedReason, setSelectedReason] = useState<string>("all");
const [productFilter, setProductFilter] = useState<string>("");

// Report Dialog State
const [reportOpen, setReportOpen] = useState(false);
const [reportReasons, setReportReasons] = useState<Set<string>>(new Set());
const [reportLoading, setReportLoading] = useState(false);

// Extract unique reasons for filter
const uniqueReasons = useMemo(() => {
    const reasons = new Set(losses.map(l => l.motivo_perda).filter(Boolean));
    return Array.from(reasons).sort();
}, [losses]);

const openReportDialog = () => {
    setReportReasons(new Set(uniqueReasons));
    setReportOpen(true);
};

const toggleReportReason = (reason: string) => {
    setReportReasons(prev => {
        const next = new Set(prev);
        if (next.has(reason)) next.delete(reason);
        else next.add(reason);
        return next;
    });
};

// --- Filter Logic ---
const filteredLosses = useMemo(() => {
    if (!dateRange?.from) return losses;

    return losses.filter(l => {
        // 1. Date Filter
        if (!l.data_identificacao) return false;
        const date = parseISO(l.data_identificacao);
        if (!isValid(date)) return false;

        const from = dateRange.from as Date;
        const to = dateRange.to || dateRange.from || new Date();

        const target = date.getTime();
        const startStr = new Date(from).setHours(0, 0, 0, 0);
        const endStr = new Date(to).setHours(23, 59, 59, 999);

        if (target < startStr || target > endStr) return false;

        // 2. Store Filter
        if (selectedStore !== "all" && String(l.loja_id) !== selectedStore) return false;

        // 3. Reason Filter
        if (selectedReason !== "all" && l.motivo_perda !== selectedReason) return false;

        // 4. Product Filter
        if (productFilter && !((l.produto_nome_perda || "").toLowerCase().includes(productFilter.toLowerCase()))) return false;

        return true;
    });
}, [losses, dateRange, selectedStore, selectedReason, productFilter]);

// --- Analytics Logic ---
const analytics = useMemo(() => {
    const totalRecords = filteredLosses.length;
    const totalQuantity = filteredLosses.reduce((acc, curr) => acc + (Number(curr.quantidade) || 0), 0);
    const totalValue = filteredLosses.reduce((acc, curr) => acc + (Number(curr.valor_estimado) || 0), 0);

    // Daily Averages
    const daysDiff = dateRange?.from && dateRange?.to
        ? Math.max(1, differenceInDays(dateRange.to, dateRange.from) + 1) // +1 to include both start and end dates
        : 30;

    const avgDailyQty = totalQuantity / daysDiff;
    const avgDailyVal = totalValue / daysDiff;

    // Grouping Logic (Dynamic: Day if < 60 days, Month otherwise)
    const isDailyGroup = daysDiff < 60;

    const byHour: Record<number, number> = {};
    const byUser: Record<number, number> = {};
    const byStore: Record<string, number> = {};         // Qty

