export default function VerificacaoPerdas() {
  useMiaPageContext({
    description: 'Verificação de Perdas — lançar perda por produto/lote/loja, conferir histórico, fotografar, justificar.',
    natural_language_hints: '"lançar perda" = aba Lançar (form); "histórico" = aba Histórico (lista); "perda hoje" = filtro data; lote/validade são obrigatórios; foto opcional mas recomendada.',
    capabilities: ['lancar_perda', 'consultar_historico', 'aprovar', 'foto_perda'],
    destructive_actions: ['excluir_perda'],
    primary_entity: 'perda',
  });
  const navigate = useNavigate();
  const [isLeaving, setIsLeaving] = useState(false);
  const [losses, setLosses] = useState<LossItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeTab, setActiveTab] = useState("lancar");
  const { toast } = useToast();
  const isMobile = useIsMobile();

  // Stores, Products, and Users
  const [stores, setStores] = useState<{ id: number; nome: string }[]>([]);
  const [loadingStores, setLoadingStores] = useState(false);
  const [products, setProducts] = useState<{ id: number; nome: string; preco_custo: number | null }[]>([]);
  const [loadingProducts, setLoadingProducts] = useState(false);
  const [users, setUsers] = useState<{ id: number; nome: string }[]>([]);
  const [currentUserId, setCurrentUserId] = useState<number | null>(null);

  // Filters
  const [filterStore, setFilterStore] = useState<string>("all");
  const [filterProduct, setFilterProduct] = useState<string>("");
  const [filterDateStart, setFilterDateStart] = useState<string>("");
  const [filterDateEnd, setFilterDateEnd] = useState<string>("");

  // Form State
  const [selectedStore, setSelectedStore] = useState<string>("");
  const [selectedProductQuery, setSelectedProductQuery] = useState("");
  const [selectedProductId, setSelectedProductId] = useState<string>("");
  const [quantity, setQuantity] = useState("");
  const [unit, setUnit] = useState("uni");
  const [reason, setReason] = useState("");
  const [obs, setObs] = useState("");
  const [lote, setLote] = useState("");
  const [validade, setValidade] = useState("");
  const [photoFile, setPhotoFile] = useState<File | null>(null);
  const [photoPreview, setPhotoPreview] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const isCapturingPhotoRef = useRef(false);

  // Chaves de sessionStorage para sobreviver ao kill da aba quando a câmera nativa
  // toma foreground no mobile (iOS Safari principalmente). Sem isso, o state da foto
  // se perde ao remount e o usuário vê o form "voltar do início" sem mensagem.
  const PHOTO_STORAGE_KEYS = {
    dataUrl: 'verificacaoPerdas:capturedImage',
    name: 'verificacaoPerdas:capturedImageName',
    type: 'verificacaoPerdas:capturedImageType',
    capturing: 'verificacaoPerdas:isCapturingPhoto',
  } as const;

  const clearPhotoStorage = () => {
    try {
      sessionStorage.removeItem(PHOTO_STORAGE_KEYS.dataUrl);
      sessionStorage.removeItem(PHOTO_STORAGE_KEYS.name);
      sessionStorage.removeItem(PHOTO_STORAGE_KEYS.type);
      sessionStorage.removeItem(PHOTO_STORAGE_KEYS.capturing);
    } catch {
      // ignore — sessionStorage pode estar bloqueado em modo privado
    }
  };

  const { hasPermission, canViewEstoque, isAdmin, loading: permissionsLoading } = usePermissions();
  const hasAccess = hasPermission("view_verificacao_perdas") || canViewEstoque() || isAdmin();

  // Photo handling
  const handlePhotoSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    isCapturingPhotoRef.current = false;
    sessionStorage.removeItem(PHOTO_STORAGE_KEYS.capturing);
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      setPhotoFile(file);
      const reader = new FileReader();
      reader.onload = (ev) => {
        const dataUrl = ev.target?.result as string;
        setPhotoPreview(dataUrl);
        try {
          sessionStorage.setItem(PHOTO_STORAGE_KEYS.dataUrl, dataUrl);
          sessionStorage.setItem(PHOTO_STORAGE_KEYS.name, file.name);
          sessionStorage.setItem(PHOTO_STORAGE_KEYS.type, file.type);
        } catch {
          // ignore — sessionStorage cheio ou bloqueado; foto continua em memória
        }
      };
      reader.readAsDataURL(file);
    }
    // Permite re-selecionar o mesmo arquivo
    e.target.value = "";
  };

  const handlePhotoAreaClick = () => {
    if (!fileInputRef.current) return;
    sessionStorage.setItem(PHOTO_STORAGE_KEYS.capturing, 'true');
    isCapturingPhotoRef.current = true;
    fileInputRef.current.click();
  };

  const clearForm = () => {
    setSelectedProductQuery("");
    setSelectedProductId("");
    setQuantity("");
    setUnit("uni");
    setReason("");
    setObs("");
    setLote("");
    setValidade("");
    setPhotoFile(null);
    setPhotoPreview(null);
    clearPhotoStorage();
    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  const fetchLosses = async () => {
    try {
      setLoading(true);
      const { data, error } = await supabase
        .from("perdas")
        .select(`
          id,
          motivo_perda,
          observacoes,
          valor_estimado,
          preco_unitario,
          data_identificacao,
          produto_nome_perda,
          produto_master_id,
          quantidade,
          responsavel_id,
          loja_id,
          foto_url,
          unidade,
          lote,
          validade,
          verificada,
          stores:lojas(id, nome),
          produtos_master(preco_custo)
        `)
        .order("data_identificacao", { ascending: false });

      if (error) throw error;
      setLosses((data as any) || []);
    } catch (err: any) {
      console.error("Erro ao carregar perdas:", err);
      toast({
        title: "Erro",
        description: "Não foi possível carregar o histórico de perdas.",
        variant: "destructive",
      });
    } finally {
      setLoading(false);
    }
  };

content.text:
Agora vou compilar minha análise minuciosa. Identifiquei múltiplos bugs de lógica críticos:

---

## ANÁLISE CRÍTICA - BUGS DE LÓGICA ENCONTRADOS

### **1. MUTAÇÃO DE DATES EM `entriesInRange` (CRÍTICO)**

**Linhas afetadas:** 952-960 (PerdasPdfGenerator.ts)

```typescript
function entriesInRange(entries: PerdasGeralEntry[], start: Date, end: Date): PerdasGeralEntry[] {
  const s = new Date(start); s.setHours(0, 0, 0, 0);  // ← MUTAÇÃO!
  const e = new Date(end); e.setHours(23, 59, 59, 999); // ← MUTAÇÃO!
  return entries.filter(en => {
    if (!en.date) return false;
    const d = new Date(en.date);
    return d >= s && d <= e;
  });
}
```

**Problema:** Embora `new Date()` crie uma cópia, `setHours()` **muta o objeto**. Se `start`/`end` forem reutilizados depois (ex: em loop semanal), são passados com horas já modificadas.

**Cenário de bug:** Em `generatePerdasGeralPdf` linhas 1170-1177, `weeks.map()` itera e chama `entriesInRange(entries, w.start, w.end)`. Se `w.start` ou `w.end` forem mutados, **perdas caem nas semanas erradas**.

**Severidade:** CRÍTICO

**Correção:** Não mutar o objeto original:
```typescript
function entriesInRange(entries: PerdasGeralEntry[], start: Date, end: Date): PerdasGeralEntry[] {
  const s = new Date(start.getTime()); s.setHours(0, 0, 0, 0);
  const e = new Date(end.getTime()); e.setHours(23, 59, 59, 999);
  return entries.filter(en => {
    if (!en.date) return false;
    const d = new Date(en.date);
    return d >= s && d <= e;
  });
}
```
Ou melhor: **não** mutar em `new Date()` — criar sem setHours e comparar separadamente.

---

### **2. INCONSISTÊNCIA DE FILTRAGEM: Dashboard vs. PDF (CRÍTICO)**

**Linhas afetadas:**
- Dashboard: **213-220** (LossAnalyticsDashboard.tsx)
- PDF Geral: **488-494** (LossAnalyticsDashboard.tsx)

**Dashboard:**
```typescript
const target = date.getTime();
const startStr = new Date(from).setHours(0, 0, 0, 0);  // ← MUTA from!
const endStr = new Date(to).setHours(23, 59, 59, 999);  // ← MUTA to!
if (target < startStr || target > endStr) return false;
```

**PDF Geral:**
```typescript
const startMs = new Date(start).setHours(0, 0, 0, 0);
const endMs = new Date(end).setHours(23, 59, 59, 999);
return t >= startMs && t <= endMs;
```

**Problema:**
- `setHours()` **retorna o timestamp**, não a Date — ambos os códigos usam timestamp, está OK aqui
- MAS: `new Date(from).setHours()` muta a cópia imediatamente (e retorna timestamp). **OK**.
- **PORÉM**: Estes são **logicamente idênticos**, mas em `splitIntoWeeks` linhas 162-165 usa outra abordagem:
  ```typescript
  const bucketStart = new Date(range.start);
  bucketStart.setHours(0, 0, 0, 0);
  ```
  Aqui **muta** e **não usa return value**. Risco de confusão.

**Cenário:** Perda às 23:40 UTC no dia X pode:
- Cair no dia X no fuso UTC
- Cair no dia Y se fuso local está atrás

Todos os 3 handlers usam `parseISO()` → `getTime()` (timezone-agnostic em ISO), então deve estar OK. **MAS** se alguém mudar para `.toISOString()` local depois, diverge.

**Severidade:** MÉDIO (funciona hoje, mas frágil)

**Verificação:** Todos usam `parseISO(date_string)` → `getTime()`. OK.

---

### **3. BUG CRÍTICO: `splitIntoWeeks` — TIMEZONE DRIFT EM PARSING**

**Linhas:** 156-184 (PerdasPdfGenerator.ts)

```typescript
export function splitIntoWeeks(
  entries: PerdasEntry[],
  start: Date,
  end: Date,
): WeekBucket[] {
  return computeWeekRanges(start, end).map(range => {
    const bucketStart = new Date(range.start);
    bucketStart.setHours(0, 0, 0, 0);
    const bucketEnd = new Date(range.end);
    bucketEnd.setHours(23, 59, 59, 999);

    const bucketEntries = entries.filter(e => {
      if (!e.date) return false;
      const d = new Date(e.date);  // ← PARSING ISO STRING!
      return d >= bucketStart && d <= bucketEnd;
    });
```

**Problema:**
- `range.start` e `range.end` são Date objects criados em `computeWeekRanges()` — existem em timezone local
- `e.date` é **string ISO** (ex: `"2026-05-15T22:40:00+00:00"`)
- `new Date("2026-05-15T22:40:00+00:00")` é **timestamp absoluto** (respeita `+00:00`)
- Mas `bucketStart.setHours(0,0,0,0)` assume **hora local** 00:00

**Cenário concreto:**
- Timestamp ISO: `"2026-05-15T22:40:00+00:00"` = UTC 22:40
- Em São Paulo (UTC-3), isto é 19:40 local
- `new Date("2026-05-15T22:40:00+00:00")` = Object { horas em UTC }
- `bucketStart.setHours(0,0,0,0)` = 00:00 **local** = 03:00 UTC próximo dia
- **Comparação mismatch**: timestamp UTC vs. hora local!

**Severidade:** CRÍTICO (perda pode cair dia errado)

**Verificação rápida:** Confirmar que `e.date` sempre tem timezone explícito ou é sempre UTC.

---

### **4. BUG: `handleGenerateGeralReport` FILTRA MAS PASSA `dateStart/dateEnd` STRING (MÉDIO)**

**Linhas:** 473-519 (LossAnalyticsDashboard.tsx)

```typescript
const handleGenerateGeralReport = async () => {
    const start = dateRange.from;  // Date object
    const end = dateRange.to || dateRange.from;  // Date object
    const dateStart = format(start, 'yyyy-MM-dd');  // String!
    const dateEnd = format(end, 'yyyy-MM-dd');  // String!

    const startMs = new Date(start).setHours(0, 0, 0, 0);
    const endMs = new Date(end).setHours(23, 59, 59, 999);

    // Filtra aqui com TIMESTAMPS
    const entries: PerdasGeralEntry[] = losses
      .filter(l => {
        const t = d.getTime();  // timezone-aware
        return t >= startMs && t <= endMs;  // ← CORRETO
      })
      .map(l => ({...}));

    // Mas PASSA STRINGS AO PDF
    await generatePerdasGeralPdf({ entries, periodoLabel, dateStart, dateEnd });
```

Em `generatePerdasGeralPdf` linhas 1170-1172:
```typescript
const weeks = computeWeekRanges(
  new Date(dateStart + 'T00:00:00'),  // ← STRING SEM TIMEZONE!
  new Date(dateEnd + 'T00:00:00'),    // ← Interpreta como LOCAL!
);
```

**Problema:** Passar string `'2026-05-15T00:00:00'` sem `Z` ou `+00:00` faz JS interpretar como hora **local**, não UTC. Pode divergir do filtro que usou timestamp UTC.

**Cenário:** 
- Dashboard filtra com timezone (UTC-aware via `parseISO()`)
- PDF gera semanas com `new Date('2026-05-15T00:00:00')` → local

**Severidade:** MÉDIO (divergência entre períodos)

**Correção:** Passar `dateStart + 'T00:00:00Z'` com `Z`.

---

### **5. BUG: `aggregateGeral` — DIVISÃO POR ZERO IMPLÍCITA (MÉDIO)**

**Linhas:** 906-949 (PerdasPdfGenerator.ts)

```typescript
export function aggregateGeral(entries: PerdasGeralEntry[]): GeralAggregate {
  if (entries.length === 0) {
    return { totalValue: 0, totalRecords: 0, storeCount: 0, lojaCritica: '-', concentracao: 0, byStore: [] };
  }

  const totalValue = entries.reduce((s, e) => s + e.val, 0);
  // ... aggregation code ...

  const byStore: GeralStoreRow[] = Array.from(storeMap.entries())
    .map(([store, d]) => ({
      store,
      value: d.value,
      count: d.count,
      pct: totalValue > 0 ? (d.value / totalValue) * 100 : 0,  // ← OK
    }))
    .sort((a, b) => b.value - a.value);

  const concentracao = byStore.length > 0 ? byStore[0].pct : 0;  // ← OK
```

**Aparentemente OK**, mas:

**Cenário problema:** Se `totalValue = 0` mas `entries.length > 0`, então todas as lojas têm `pct = 0` e `concentracao = 0`. Isto é **correto logicamente**, mas visualmente confuso (pode parecer que não há dados).

Na verdade, **isto não é bug**, é edge case tratado corretamente.

**Severidade:** BAIXO (não há bug, só edge case)

---

### **6. BUG: `drawVerticalBars` / `drawStoreBars` — AUSÊNCIA DE TRATAMENTO `maxVal = 0`**

**Linhas afetadas:**
- `drawVerticalBars`: **301** (PerdasPdfGenerator.ts)
- `drawStoreBars`: **979** (PerdasPdfGenerator.ts)
- `drawHorizontalBars`: **245** (PerdasPdfGenerator.ts)

```typescript
// drawVerticalBars
const maxVal = Math.max(...items.map(i => i.value), 1);  // ← DEFAULT 1, OK

// drawStoreBars
const maxVal = Math.max(...items.map(i => i.value), 1);  // ← DEFAULT 1, OK

// drawHorizontalBars
const maxVal = Math.max(...items.map(i => i.value), 1);  // ← DEFAULT 1, OK
```

Todos usam `Math.max(..., 1)`, então divisão por zero é evitada. **OK**.

**Severidade:** NENHUMA (está correto)

---

### **7. BUG: `ensureSpace` NÃO VALIDA CURSORY FINAL (MÉDIO)**

**Linhas:** 214-227 (PerdasPdfGenerator.ts)

```typescript
function ensureSpace(
  doc: jsPDF,
  cursorY: number,
  neededMm: number,
  pageHeight: number,
  drawPageExtras: (hookData: { pageNumber?: number }) => void,
): number {
  if (cursorY + neededMm > pageHeight - 22) {  // 22mm é footer/margin
    doc.addPage();
    drawPageExtras({ pageNumber: doc.getNumberOfPages() });
    return 52;  // ← HARDCODED! Assume header = 52mm
  }
  return cursorY;
}
```

**Problema:** Se `neededMm` é **muito grande** (ex: 70mm), mas `pageHeight - 22 = 278mm` (padrão A4 = 297 - 22), então:
- Não entra no `if` se `cursorY` está baixo
- Tenta desenhar 70mm mas espaço real é <70mm
- **Overflow silencioso** — conteúdo sai da página

**Cenário:** Relatório com muitas lojas na semana → barras de loja ocupam >70mm, mas `ensureSpace()` não entra no `if` porque calcula margem incorreta.

**Severidade:** MÉDIO (conteúdo pode sair da página)

**Correção:** 
```typescript
if (cursorY + neededMm > pageHeight - 22) {
  doc.addPage();
  drawPageExtras({ pageNumber: doc.getNumberOfPages() });
  return 52;
}
// Validação adicional:
if (52 + neededMm > pageHeight - 22) {
  // Conteúdo é tão grande que não cabe em nova página
  console.warn(`Conteúdo de ${neededMm}mm não cabe em página`);
}
```

---

### **8. BUG: HARDCODED MARGIN 22MM VS HEADER/FOOTER REAIS (MÉDIO)**

**Linhas afetadas:** 
- `ensureSpace`: 221
- `generatePerdasPdf`: 444 (cursorY = 52)
- `generatePerdasGeralPdf`: 1125 (cursorY = 52)

Header real:
```typescript
doc.line(15, 43, pageWidth - 15, 43);  // Footer está em pageHeight - 12
```

Margin bottom = 12mm (linha 416, 1097), mas `ensureSpace()` usa **22mm**. Discrepância!

Se conteúdo é desenhado muito perto do bottom, pode sobrepor footer.

**Severidade:** MÉDIO

**Correção:** Usar constante:
```typescript
const MARGIN_BOTTOM = 12;
if (cursorY + neededMm > pageHeight - MARGIN_BOTTOM) { ... }
```

---

### **9. BUG: `splitIntoWeeks` + `aggregatePerdas` — PERDA ÓRFÃ FORA DE SEMANAS (CRÍTICO)**

**Linhas afetadas:** 489-622 (PerdasPdfGenerator.ts - modo semanal)

```typescript
if (dividirEmSemanas && dateStart && dateEnd) {
  const weeks = splitIntoWeeks(
    entries,
    new Date(dateStart + 'T00:00:00'),  // ← STRING, TIMEZONE BUG (vide item 4)
    new Date(dateEnd + 'T00:00:00'),
  );
```

E em `splitIntoWeeks`:
```typescript
const bucketStart = new Date(range.start);
bucketStart.setHours(0, 0, 0, 0);
// ...
const d = new Date(e.date);  // PARSING ISO
return d >= bucketStart && d <= bucketEnd;
```

**Cenário crítico:**
- Período: 01/05 a 31/05 (31 dias)
- `computeWeekRanges()` gera: Semana 1 (01-07), Semana 2 (08-14), ..., Semana 5 (29-31)
- Se perda cair em 31/05 mas hora UTC > hora local esperada, pode divergir e cair **fora** de Semana 5
- **Resultado:** Perda não aparece em nenhuma semana!

Pior: Seção "RANKING DE LOJAS · PERÍODO" (linhas 1198-1214 em PDF) agrega **todo o período**, pode incluir a perda órfã. Mas na "TENDÊNCIA SEMANAL", perda não aparece → **números divergem**.

**Severidade:** CRÍTICO (inconsistência crítica)

**Verificação necessária:** Testar com data ISO com timezone que causa +1 dia em conversão local.

---

### **10. BUG: `delta` SEMANAL COM DIVISÃO POR ZERO IMPLÍCITA (MÉDIO)**

**Linhas:** 
- PDF Perdas: 571-579
- PDF Geral: 1271-1279

```typescript
if (prevWeek && prevWeek.aggregate.totalValue > 0) {
  const delta = ((wAgg.totalValue - prevWeek.aggregate.totalValue) / prevWeek.aggregate.totalValue) * 100;
```

**Problema:** Se `prevWeek.totalValue = 0`, a comparação `> 0` evita divisão. **OK**.

**MAS:** Se **semana atual** tem totalValue = 0 e anterior > 0, delta = (0 - prev) / prev = **negativo**, mostra ▼ verde. Correto (melhora).

Se **semana atual** > 0 mas anterior = 0, delta **não é calculado** (condicional falha). **OK**, não mostra delta.

**Está correto!**

**Severidade:** NENHUMA

---

### **11. BUG: `aggregatePerdas` RETORNA ARRAY VAZIO MAS `top10Produtos` TEM 0 ELEMENTOS (BAIXO)**

**Linhas:** 99-104

```typescript
const top10Produtos = sortedProds.slice(0, 10).map(([produto, d], i) => ({
  rank: i + 1,
  produto,
  qty: d.qty,
  value: d.value,
}));
```

Se `sortedProds.length = 0`, `.slice(0, 10)` = `[]`, `.map()` = `[]`. **OK**.

Se `sortedProds.length = 5`, `.slice(0, 10)` = array 5 elementos, ranks 1-5. **OK**.

Isto está correto!

**Severidade:** NENHUMA

---

### **12. BUG: FALTA VALIDAÇÃO `entries.length === 0` EM PDF GERAÇÃO (BAIXO)**

**Linhas:** 350-352 (generatePerdasPdf)

```typescript
export async function generatePerdasPdf(params: GeneratePerdasPdfParams): Promise<void> {
  const { entries, periodoLabel, lojaLabel, motivosLabel, dividirEmSemanas = false, dateStart, dateEnd } = params;
  const agg = aggregatePerdas(entries);
```

Se `entries = []`, `agg` retorna zeros/strings vazias, mas PDF **ainda é gerado** (vazio). Isto é OK, mas talvez deveria avisar.

Handler em Dashboard (linhas 424-426) **já valida**:
```typescript
if (!reportData.length) {
  toast.error("Sem dados para os motivos selecionados.");
  return;
}
```

Então este é apenas um defense-in-depth OK.

**Severidade:** NENHUMA (validado no caller)

---

### **RESUMO DE BUGS CRÍTICOS:**

| # | Bug | Linha | Severidade | Impacto |
|---|-----|-------|-----------|---------|
| 1 | Mutação de Dates em `entriesInRange` | 952-960 | CRÍTICO | Semanas perdem perdas |
| 2 | Inconsistência filtragem Dashboard vs PDF | 213-220 vs 488-494 | MÉDIO | Período pode divergir |
| 3 | Timezone drift em `splitIntoWeeks` | 169 | CRÍTICO | Perda cai dia errado |
| 4 | `dateStart/dateEnd` sem `Z` em PDF Geral | 1170-1172 | MÉDIO | Período local vs UTC |
| 7 | `ensureSpace` hardcoded 22mm inadequado | 221 | MÉDIO | Overflow silencioso |
| 8 | Margin 22mm vs footer 12mm | 221 vs 416 | MÉDIO | Sobreposição footer |
| 9 | Perda órfã fora de semanas | 489-622 | CRÍTICO | Rankings divergem |

---

## BUGS REPORTADOS (ORDENADOS POR SEVERIDADE):

### **CRÍTICO #1: Mutação de Dates em `entriesInRange`**
- **Arquivo:** `PerdasPdfGenerator.ts`
- **Linhas:** 952-954
- **Código:**
```typescript
const s = new Date(start); s.setHours(0, 0, 0, 0);
const e = new Date(end); e.setHours(23, 59, 59, 999);
```
- **Problema:** `setHours()` muta o objeto. Em loop de semanas (linha 1175), `w.start/w.end` são reutilizados e acabam com horas modificadas, causando perdas caírem em semanas erradas.
- **Correção:** Usar `.getTime()` para clonar ou não mutar:
```typescript
const s = new Date(start.getTime()); s.setHours(0, 0, 0, 0);
```

---

### **CRÍTICO #2: Timezone Drift em `splitIntoWeeks`**
- **Arquivo:** `PerdasPdfGenerator.ts`
- **Linha:** 169
- **Código:**
```typescript
const d = new Date(e.date);  // e.date = ISO string "2026-05-15T22:40:00+00:00"
return d >= bucketStart && d <= bucketEnd;
```
- **Problema:** `new Date(iso_string)` preserva timestamp UTC, mas `bucketStart.setHours(0,0,0,0)` assume hora **local**. Comparação mismatch: UTC vs local. Perda às 22:40 UTC pode cair no dia errado em fuso local.
- **Correção:** Normalizar ambos para timestamp UTC ou ambos para hora local:
```typescript
const d = new Date(e.date);
const dUtc = d.toISOString().substring(0, 10);  // "2026-05-15"
const bucketStartUtc = format(bucketStart, 'yyyy-MM-dd');  // usa bucketStart em local
// Compare strings de data, não timestamps mistos
```

---

### **CRÍTICO #3: Perda Órfã Fora de Semanas — Inconsistência Período**
- **Arquivo:** `PerdasPdfGenerator.ts`
- **Linhas:** 1204 vs 507
- **Código:**
```typescript
// Linha 1204: Seção RANKING DE LOJAS (agrega TODO período)
doc.text('RANKING DE LOJAS · PERÍODO', 15, cursorY);
// ... desenha byStore que é agregado de TODAS as entries

// Mas em splitIntoWeeks (linha 169), perda pode não entrar em nenhuma semana se timezone divergir
// Resultado: Ranking mostra perda X, mas Tendência Semanal não mostra
```
- **Problema:** Se `entriesInRange()` tem bug de mutação ou `splitIntoWeeks()` tem drift timezone, uma perda pode ser agregada no "RANKING DO PERÍODO" (que usa `aggregateGeral(entries)` direto) mas **não aparecer em nenhuma semana**. Numbers divergem.
- **Correção:** Após `splitIntoWeeks()`, validar que toda perda caiu em alguma semana:
```typescript
const weekTotals = weeks.map(w => w.entries.length).reduce((a,b) => a+b, 0);
if (weekTotals !== entries.length) console.warn('Perdas órfãs fora de semanas');
```

---

### **MÉDIO #1: `dateStart/dateEnd` String Sem `Z` em PDF Geral**
- **Arquivo:** `LossAnalyticsDashboard.tsx`
- **Linhas:** 480-481, passados a 1170-1172
- **Código:**
```typescript
const dateStart = format(start, 'yyyy-MM-dd');  // "2026-05-15"
const dateEnd = format(end, 'yyyy-MM-dd');      // "2026-05-31"
// Passados ao gerador que faz:
new Date(dateStart + 'T00:00:00');  // Interpreta como LOCAL, não UTC!
```
- **Problema:** Dashboard filtra com `parseISO(d.data_identificacao)` que é **timezone-aware** (ISO com `+00`). PDF gera semanas com `new Date('2026-05-15T00:00:00')` que é **local**. Podem divergir.
- **Correção:** Passar com `Z`:
```typescript
new Date(dateStart + 'T00:00:00Z')  // Force UTC
```

---

### **MÉDIO #2: `ensureSpace` Margin Hardcoded 22mm Inadequado**
- **Arquivo:** `PerdasPdfGenerator.ts`
- **Linha:** 221
- **Código:**
```typescript
if (cursorY + neededMm > pageHeight - 22) {
  doc.addPage();
  drawPageExtras({ pageNumber: doc.getNumberOfPages() });
  return 52;
}
```
- **Problema:** Se `neededMm > 70mm` (ex: seção com muitas lojas), pode não entrar no `if` porque `pageHeight - 22 ≈ 278mm`. Conteúdo overflow silencioso.
- **Correção:** Adicionar validação:
```typescript
if (cursorY + neededMm > pageHeight - 22) {
  doc.addPage();
  drawPageExtras({ pageNumber: doc.getNumberOfPages() });
  if (52 + neededMm > pageHeight - 22) {
    console.warn(`Conteúdo ${neededMm}mm não cabe nem em página nova`);
  }
  return 52;
}
```

---

### **MÉDIO #3: Margin Bottom Inconsistente (22mm vs 12mm)**
- **Arquivo:** `PerdasPdfGenerator.ts`
- **Linhas:** 221 vs 416, 1097
- **Código:**
```typescript
// Linha 221: ensureSpace usa 22mm
if (cursorY + neededMm > pageHeight - 22) { ... }

// Mas footer está em:
doc.text(..., pageHeight - 12, ...);  // Linhas 416, 1097
```
- **Problema:** Lógica de margin usa 22mm mas footer real é 12mm. Conteúdo pode desenhar entre 12-22mm e sobrepor footer.
- **Correção:** Usar constante:
```typescript
const MARGIN_BOTTOM = 12;  // ou 15 para safe margin
if (cursorY + neededMm > pageHeight - MARGIN_BOTTOM - 5) { ... }
```

---

### **MÉDIO #4: Inconsistência de Filtragem Dashboard vs PDF**
- **Arquivo:** `LossAnalyticsDashboard.tsx`
- **Linhas:** 213-220 vs 488-494
- **Código (Dashboard):**
```typescript
const target = date.getTime();
const startStr = new Date(from).setHours(0, 0, 0, 0);  // ← Retorna timestamp
const endStr = new Date(to).setHours(23, 59, 59, 999);
if (target < startStr || target > endStr) return false;
```
- **Código (PDF Geral):**
```typescript
const startMs = new Date(start).setHours(0, 0, 0, 0);  // ← Retorna timestamp
const endMs = new Date(end).setHours(23, 59, 59, 999);
return t >= startMs && t <= endMs;
```
- **Problema:** Ambos usam `setHours()` que **retorna timestamp**, mas a abordagem em `splitIntoWeeks()` (linhas 162-165) é diferente — cria object local. Três padrões diferentes = risco de futuro bug se refatorado.
- **Correção:** Criar helper função reutilizável:
```typescript
function getTimestampRange(from: Date, to: Date) {
  return {
    startMs: new Date(from.getTime()).setHours(0, 0, 0, 0),
    endMs: new Date(to.getTime()).setHours(23, 59, 59, 999),
  };
}
```

---

### **BAIXO #1: Falta Validação Edge Case Semanas Vazias**
- **Arquivo:** `PerdasPdfGenerator.ts`
- **Linhas:** 497-498
- **Código:**
```typescript
if (weeks.length > 0) {
  // Seção semanal
  // ... else cai para modo consolidado
}
```
- **Problema:** Se período é < 7 dias, `computeWeekRanges()` retorna 1 semana. **OK**. Mas se toda semana está vazia (`week.entries = []`), loop ainda itera e desenha seção vazia. Visualmente confuso.
- **Severidade:** BAIXO (apenas cosmética)
- **Correção:** Filtrar semanas com entries:
```typescript
const weeksWithData = weeks.filter(w => w.entries.length > 0);
if (weeksWithData.length > 0) { ... }
```

---

## CONCLUSÃO

**3 BUGS CRÍTICOS:**
1. Mutação de Dates em `entriesInRange` — quebra bucketização semanal
2. Timezone drift em `splitIntoWeeks` — perda cai dia errado
3. Perda órfã fora de semanas — inconsistência período vs semanas

**Recomendação:** Corrigir críticos #1 e #2 **imediatamente**. Testar com datas ISO contendo timezone explícito (`+00:00` ou local).

