input.new_string:
const toggleStore = (id: number) => {
    setSelectedStoreIds(prev => {
        // Estado "nenhuma" (sentinel -1): clicar inicia uma seleção só com a clicada.
        if (prev.has(-1)) return new Set<number>([id]);
        // Estado "todas" (Set vazio): parte de todas; senão parte da seleção atual.
        const next = new Set<number>(prev.size === 0 ? stores.map(s => s.id) : prev);
        if (next.has(id)) next.delete(id); else next.add(id);
        // Voltou a ter todas → normaliza pra vazio (=todas).
        if (next.size === stores.length) return new Set<number>();
        // Ficou sem nenhuma → marca o sentinel "nenhuma".
        if (next.size === 0) return new Set<number>([-1]);
        return next;
    });
};

